import torch
import torch.nn as nn
from torch.utils.data import DataLoader, TensorDataset

from .model import TASKS, ResidualMLP


# Baseline settings. Deliberately plain so they are easy to beat:
# plain SGD, constant learning rate, no dropout, no schedule, no augmentation.
LEARNING_RATE = 0.05
BATCH_SIZE = 256
EPOCHS = {"mnist": 30, "cifar10": 30, "imagenet32": 10}




# The folling shift augmentation code is generated by claude
# conversation is #1 in prompts.txt


# Upper bound on the size of the temporary random matrix used for sampling
# (chunks of images are processed so memory stays bounded for large grids).
_MAX_RAND_ELEMS = 1 << 24

def _shift_candidates(max_shift: int, size: int) -> torch.Tensor:
    """
    Distinct circular shifts for one axis, drawn from [-max_shift, max_shift].
 
    Under wrap-around, shifts that differ by a multiple of `size` are identical,
    so if the interval is wider than `size` we keep one representative per
    residue class (a window of `size` consecutive integers containing 0).
    """
    if 2 * max_shift + 1 <= size:
        return torch.arange(-max_shift, max_shift + 1)
    start = -((size - 1) // 2)
    return torch.arange(start, start + size)
 
 
def _sample_unique(
    num_rows: int, n: int, k: int, generator: torch.Generator
) -> torch.Tensor:
    """For each of `num_rows` rows, sample k distinct indices from range(n). -> (num_rows, k)"""
    out = torch.empty(num_rows, k, dtype=torch.long)
    if k == 0:
        return out
    chunk = max(1, _MAX_RAND_ELEMS // n)
    for s in range(0, num_rows, chunk):
        e = min(s + chunk, num_rows)
        # top-k of i.i.d. uniform keys == a uniformly random k-subset, without replacement
        out[s:e] = torch.rand(e - s, n, generator=generator).topk(k, dim=1).indices
    return out
 
 
def shift_augment(
    x: torch.Tensor,
    labels: torch.Tensor,
    k: int,
    x_max_shift: int,
    y_max_shift: int,
    allow_identity: bool = False,
    generator: torch.Generator = None,
) -> tuple[torch.Tensor, torch.Tensor]:
    """
    Create k circularly-shifted copies of a dataset and append them to the original.
 
    Every image gets its OWN random shift in each copy:
      - dy: row shift (along H), an integer in [-y_max_shift, y_max_shift]
      - dx: column shift (along W), an integer in [-x_max_shift, x_max_shift]
    For each image, its k (dy, dx) pairs are sampled WITHOUT replacement, so that
    image's k shifted versions are all distinct. Different images are sampled
    independently. Shifts wrap around, like torch.roll: positive dy moves content
    down, positive dx moves it right; negative values move it up / left.
 
    Args:
        x:              (B, C, H, W) tensor.
        labels:         (B, ...) tensor of labels aligned with x along dim 0.
        k:              number of shifted copies of the dataset to create.
        x_max_shift:    max |column shift|.
        y_max_shift:    max |row shift|.
                        If 2 * max_shift + 1 > W (or H), shifts that are equivalent
                        under wrap-around are collapsed, so uniqueness still holds
                        (at most W distinct column shifts and H distinct row shifts).
        allow_identity: if False (default), the (0, 0) shift is excluded, since it
                        would duplicate the original image.
        generator:      optional CPU torch.Generator for reproducibility.
 
    Returns:
        x_out:      (B * (k + 1), C, H, W) -- original dataset first, then copy 1, ..., copy k.
        labels_out: (B * (k + 1), ...)     -- labels repeated in the same order.
    """
    if x.ndim != 4:
        raise ValueError(f"x must have shape (B, C, H, W), got {tuple(x.shape)}")
    if labels.ndim < 1 or labels.shape[0] != x.shape[0]:
        raise ValueError(
            f"labels must have the same size as x along dim 0 "
            f"(x: {x.shape[0]}, labels: {tuple(labels.shape)})"
        )
    if k < 0 or x_max_shift < 0 or y_max_shift < 0:
        raise ValueError("k, x_max_shift and y_max_shift must be non-negative")
 
    B, C, H, W = x.shape
    dev = x.device
 
    # Candidate shift values per axis; a (dy, dx) pair is a flat index iy * n_x + ix.
    cand_y = _shift_candidates(y_max_shift, H)
    cand_x = _shift_candidates(x_max_shift, W)
    n_y, n_x = len(cand_y), len(cand_x)
    n_total = n_y * n_x
    identity = cand_y.tolist().index(0) * n_x + cand_x.tolist().index(0)
 
    n_available = n_total if allow_identity else n_total - 1
    if k > n_available:
        raise ValueError(
            f"Requested k={k} unique shifts per image, but only {n_available} are "
            f"available (row shifts: {n_y} distinct, column shifts: {n_x} distinct"
            f"{'' if allow_identity else ', excluding (0, 0)'})."
        )
 
    # --- Sample k unique flat indices per image: (B, k) ---
    if allow_identity:
        flat = _sample_unique(B, n_total, k, generator)
    else:
        # Sample from n_total - 1 slots, then skip over the identity's slot.
        flat = _sample_unique(B, n_total - 1, k, generator)
        flat = flat + (flat >= identity).long()
    dy = cand_y[flat // n_x].to(dev)  # (B, k)
    dx = cand_x[flat % n_x].to(dev)   # (B, k)
 
    # --- Build output: original, then one block of B images per copy ---
    x_out = x.new_empty((B * (k + 1), C, H, W))
    x_out[:B] = x
 
    ar_h = torch.arange(H, device=dev)
    ar_w = torch.arange(W, device=dev)
    b_idx = torch.arange(B, device=dev)[:, None, None, None]
    c_idx = torch.arange(C, device=dev)[None, :, None, None]
    for j in range(k):
        # Per-image circular roll via gather: out[h, w] = in[(h - dy) % H, (w - dx) % W]
        rows = (ar_h[None, :] - dy[:, j, None]) % H  # (B, H)
        cols = (ar_w[None, :] - dx[:, j, None]) % W  # (B, W)
        x_out[(j + 1) * B : (j + 2) * B] = x[
            b_idx, c_idx, rows[:, None, :, None], cols[:, None, None, :]
        ]
 
    labels_out = labels.repeat((k + 1,) + (1,) * (labels.ndim - 1))
    return x_out, labels_out


def prepare(X, y=None):
    """Convert uint8 images (0-255) to floats in roughly [-1, 1]."""

    # if no y, assume it's test data
    if y is None:
        return (X / 255.0 - 0.5) / 0.5


    X, y = shift_augment(
        torch.as_tensor(X).float(),
        y,
        3,
        5,
        5
    )

    print(f"Post augmentation dataset shape: {X.shape}")

    X_normed = (X / 255.0 - 0.5) / 0.5

    return X_normed, y


# ---------------------------------------------------------------------------
# The two functions below are the REQUIRED INTERFACE for every submission.
# The grading notebook calls them like this:
#
#     model = train("cifar10", X_train, y_train, seed=0, device="cuda")
#     probs = predict(model, X_test)
#
# Change anything inside them, but keep their names and arguments.
# ---------------------------------------------------------------------------

def train(task, X_train, y_train, seed=0, device="cuda"):
    """Build a new model and train it from scratch. Returns the trained model."""
    torch.manual_seed(seed)                   # makes the run reproducible

    # 1. Build the model for this task. Only input size and class count differ.
    model = ResidualMLP(**TASKS[task]).to(device)

    # 2. Wrap the data so we can loop over shuffled mini-batches.
    dataset = TensorDataset(*prepare(X_train, torch.as_tensor(y_train).long()))
    loader = DataLoader(dataset, batch_size=BATCH_SIZE, shuffle=True)

    # 3. Choose the loss and the optimizer.
    loss_fn = nn.CrossEntropyLoss()           # expects raw logits
    optimizer = torch.optim.SGD(model.parameters(), lr=LEARNING_RATE)

    # 4. The training loop.
    model.train()
    for epoch in range(EPOCHS[task]):
        total_loss = 0.0
        for X_batch, y_batch in loader:
            X_batch, y_batch = X_batch.to(device), y_batch.to(device)

            logits = model(X_batch)           # forward pass
            loss = loss_fn(logits, y_batch)   # how wrong are we?

            optimizer.zero_grad()             # clear old gradients
            loss.backward()                   # backward pass: compute gradients
            optimizer.step()                  # update the weights

            total_loss += loss.item() * len(X_batch)

        print(f"epoch {epoch + 1}: train loss {total_loss / len(dataset):.4f}")

    return model


def predict(model, X):
    """Return class probabilities for X, one row per example, on the CPU."""
    device = next(model.parameters()).device
    X = prepare(X)
    # Predict in chunks so a large test set does not run out of GPU memory.
    chunks = [model.predict(X[i:i + 1024].to(device)).cpu() for i in range(0, len(X), 1024)]
    return torch.cat(chunks)
